package com.example.data.local

object DuaTranslationLocalization {

    fun getLocalizedTranslation(
        duaId: Int,
        language: String,
        defaultTranslation: String,
        hausa: String = "",
        yoruba: String = "",
        igbo: String = ""
    ): String {
        return when (language) {
            "Hausa" -> if (hausa.isNotBlank()) hausa else getHausaTranslation(duaId) ?: defaultTranslation
            "Yoruba" -> if (yoruba.isNotBlank()) yoruba else getYorubaTranslation(duaId) ?: defaultTranslation
            "Igbo" -> if (igbo.isNotBlank()) igbo else getIgboTranslation(duaId) ?: defaultTranslation
            "Arabic" -> getArabicExplanation(duaId) ?: defaultTranslation
            "French" -> getFrenchTranslation(duaId) ?: defaultTranslation
            "Spanish" -> getSpanishTranslation(duaId) ?: defaultTranslation
            "Urdu" -> getUrduTranslation(duaId) ?: defaultTranslation
            "Chinese" -> getChineseTranslation(duaId) ?: defaultTranslation
            else -> defaultTranslation
        }
    }

