    private fun getHausaTranslation(id: Int): String? =
        DuaDatabaseSeeder.getSeedDuas().find { it.id == id }?.translationHausa?.takeIf { it.isNotBlank() }

    private fun getYorubaTranslation(id: Int): String? =
        DuaDatabaseSeeder.getSeedDuas().find { it.id == id }?.translationYoruba?.takeIf { it.isNotBlank() }

    private fun getIgboTranslation(id: Int): String? =
        DuaDatabaseSeeder.getSeedDuas().find { it.id == id }?.translationIgbo?.takeIf { it.isNotBlank() }
